      flag = "Reagent cost in Forever not confirmed",
      sources = { "https://www.icy-veins.com/wow-forever/arcane-mage-ranged-dps-pve-guide", "https://www.icy-veins.com/wow-forever/frost-mage-leveling", "https://www.wowhead.com/forever/guide/classes/mage/arcane/dps-leveling-tips" },
    },
    {
      id = "aoe-pulls",
      title = "AoE pulls",
      body = "Mage AoE has no target cap fall-off but costs a lot of mana. Only AoE packs of 4+ and only once the tank has them: stand near the tank for Arcane Explosion or far back with Blizzard and Flamestrike if it isn't safe. Pre-pull Flamestrike where the tank will stand.",
      unconfirmed = false,
      flag = "",
      sources = { "https://www.icy-veins.com/wow-forever/arcane-mage-leveling", "https://www.icy-veins.com/wow-forever/fire-mage-leveling", "https://www.icy-veins.com/wow-forever/frost-mage-leveling", "https://www.icy-veins.com/wow-forever/fire-mage-ranged-dps-pve-rotation-cooldowns-abilities" },
    },
    {
      id = "threat",
      title = "Watch your threat",
      body = "Mages pull aggro from tanks easily, especially with AoE and Fire crits (Ignite). Let the tank build threat first. Frost Nova and Blink buy time, Ice Barrier and Ice Block save you, and Frost talent choices (Frost Channeling, Incineration in raid builds) can lower threat.",
      unconfirmed = false,
      flag = "",
      sources = { "https://www.icy-veins.com/wow-forever/frost-mage-leveling", "https://www.icy-veins.com/wow-forever/fire-mage-ranged-dps-pve-guide", "https://www.icy-veins.com/wow-forever/arcane-mage-ranged-dps-pve-guide", "https://www.icy-veins.com/wow-forever/frost-mage-ranged-dps-pve-guide", "https://www.icy-veins.com/wow-forever/frost-mage-ranged-dps-pve-spec-builds-talents" },
    },
    {
      id = "remove-curse",
      title = "Remove Lesser Curse",
      body = "Only Mages and Druids can remove curses. Damage matters, but a group wiping to a curse only you can dispel is worse.",
      unconfirmed = false,
      flag = "",
      sources = { "https://www.icy-veins.com/wow-forever/frost-mage-ranged-dps-pve-rotation-cooldowns-abilities", "https://www.wowhead.com/forever/guide/classes/mage/frost/dps-abilities" },
    },
    {
      id = "dampen-amplify",
      title = "Dampen and Amplify Magic",
      body = "Amplify Magic gives a target more healing (and more magic damage taken), useful in heavy physical fights. Dampen Magic lowers magic damage but also healing received, so don't put it on group members by accident.",
      unconfirmed = false,
      flag = "",
      sources = { "https://www.wowhead.com/forever/guide/classes/mage/frost/dps-abilities", "https://www.wowhead.com/forever/guide/classes/mage/arcane/dps-abilities", "https://www.icy-veins.com/wow-forever/frost-mage-ranged-dps-pve-rotation-cooldowns-abilities" },
    },
    {
      id = "interrupts",
      title = "Interrupt casters",
      body = "Counterspell enemy healers and dangerous casters. It's off the global cooldown, so you lose almost nothing using it.",
      unconfirmed = false,
      flag = "",
      sources = { "https://www.icy-veins.com/wow-forever/frost-mage-ranged-dps-pve-rotation-cooldowns-abilities", "https://www.icy-veins.com/wow-forever/arcane-mage-ranged-dps-pve-rotation-cooldowns-abilities", "https://www.icy-veins.com/wow-forever/frost-mage-leveling" },
